/**
 * =================================================================
 * General layout
 * =================================================================
 */
 .fi-topbar,
 .fi-sidebar-header
 {
    @apply bg-black text-white;

    .fi-logo span {
        @apply text-white;
    }
}

.fi-sidebar-header {
    @apply shadow-none!;
    border: 0;
    height: 4rem; 
}

.fi-sidebar-group .fi-sidebar-group-label {
    @apply font-medium uppercase text-black dark:text-gray-400 tracking-widest;
}

.fi-sidebar-item {

    &-icon {display: none}
}

/**
 * page header
 */
.fi-breadcrumbs-item-label {
    @apply text-black dark:text-gray-400 font-normal tracking-wide;
}
.fi-header-heading {
    @apply font-medium;
}


// overwrite sticky header font size, back to filament default
.fi-main.is-sticky .fi-header .fi-header-heading {
    @apply text-2xl  sm:text-3xl!;
}

.is-sticky.sticky-theme-default .fi-header:before {
    @apply border-black;
}

/**
 * table
 */
 // hide default ordering button, if not inside a modal (e.g. relation manager)
 // hide default ordering button, if not inside a modal (e.g. relation manager)
.fi-ta-header-toolbar:not(.fi-modal-content *):not(.fi-resource-relation-manager *)
{
    button[wire\:click="toggleTableReordering"] {
        display: none;
    }
}


.fi-ta-table {
    .fi-ta-header-cell-label {
        @apply font-medium uppercase tracking-wider text-black dark:text-gray-400 text-xs;
    }

}

/**
 * =================================================================
 * END Layout
 * =================================================================
 */



/**
 * =================================================================
 * Components
 * =================================================================
 */
.fi-sc-section {
    @apply mb-0 mt-3 pt-0 pb-9;
}

.fi-sc-section:not(.no-border) {
    @apply  border-b border-gray-300 dark:border-white;
}
.fi-sc-section.no-border {
    @apply border-0;
}

.fi-section-header-heading {
    @apply text-xl pt-0 pb-4 font-semibold;

    &::before {
        content: '#'
    }
}

.fi-sc-actions {
    @apply mb-0 mt-2 pt-0 border-gray-300 dark:border-white;
}

// fix per colori bottoni, per renderli simili a v3.
// credits https://github.com/filamentphp/filament/discussions/17517#discussioncomment-15442863
.fi-btn {
    &:not(.fi-outlined) {
        &.fi-color {
            --bg: var(--color-600) !important;
            --text: white !important;
            --hover-bg: var(--color-500) !important;
            --hover-text: white !important;
        }
    }
}

// hide default "reorder" trigger button
// .reorder-trigger-before is rendered via a render hook
// .reorder-trigger-before + span {display: none;}


/* .fi-btn {
    // @apply py-4;
} */
/**
 * =================================================================
 * END components
 * =================================================================
 */


/**
 * =================================================================
 * Login page
 * =================================================================
 */

 // revert the padding and border removed in the minimal theme
 .fi-simple-layout:has(.afh-login-wrapper) {
    background: rgb(250, 250, 250);
    @apply dark:bg-gray-700;
}

.afh-login-wrapper {

    @apply p-12 shadow-xl rounded-xl bg-white dark:bg-gray-800;

    .fi-logo {display: none;}


    .fi-simple-header-heading {
       @apply font-medium;
    }

    .fi-ac-btn-action {
        @apply py-3;
    }
}


/**
* =================================================================
* END Login page
* =================================================================
*/


/**
 * =================================================================
 * Form
 * =================================================================
 */

/**
 * Translation section
 */
.filament-helper-translation-section.no-padding > .fi-section-content-ctn > .fi-section-content  {
    @apply p-0!
}

.filament-helper-translation-section.no-tabs-border .filament-helper-translation-tabs {
    @apply rounded-none!;
    @apply border-0!;
}

// nested translation section
.fi-sc-form .fi-sc-section .fi-section-content-ctn .filament-helper-translation-section {
    @apply border-0 px-0 py-0;
}

/**
 * Publication input
 */
.filament-helper-publication-input.uncontained {
    box-shadow: none;
}

/**
 * Relation managers
 */
form ~ .fi-resource-relation-managers {
    margin-top: 5rem;
}


/**
 * SEO Section
 */
.fi-sc-section.section-seo {
    padding-top: 0;
    margin-top: 0;
    border-bottom: 0;
    padding-bottom: 0;

    .fi-section-header .fi-icon-btn {
        order: -1;
    }

    .fi-section-header-description {
        @apply font-semibold;
    }
}

/**
 * Sticky actions
 */
.fi-sc-actions.fi-sticky .fi-ac {
    @apply bg-gray-100;
    bottom: 0 !important;
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
}

/**
 * Helper text
 */
.fi-fo-field-wrp-helper-text {
    @apply text-xs italic;
}


.fi-fo-rich-editor-main {
    min-height: 200px;
}

/**
 * =================================================================
 * END Form
 * =================================================================
 */


/**
 * =================================================================
 * Blocks builder
 * =================================================================
 */
.fi-resource-list-records-page.fi-resource-blocks {
    .fi-ta-row {
        @apply hover:bg-gray-200;
    }
}

.fi-table-cell-afh-block-preview-column {

    .fi-ta-col-wrp > a {
        display: block;
    }


    .afh-iframe-container-large {
        min-height: 500px;

        iframe {
            pointer-events: none;
            min-height: 500px;
        }
        .loader {
            width: 100%;
            height: 100%;
            position: absolute;
            left: 0;
            top: 0;
            z-index: 1;
            background: #FFF;
        }
    }
}

.fi-resource-create-record-page.fi-resource-blocks,
.fi-resource-edit-record-page.fi-resource-blocks {

    .fi-sc-form .fi-sc-section:not(.filament-helper-publication-input) {
        @apply border py-4 px-6 rounded-lg mt-0;
    }

    // nested translation section
    .fi-sc-section.no-border.filament-helper-translation-section{
        @apply border-0 px-0;
    }

    .filament-helper-blocks-build-grid .fi-section {height: 100%;}

    .filament-helper-publication-input {
        @apply border-0;
    }

    .fi-form {
        .filepond--drip,
        .filepond--panel-root {
            @apply border-0!;
        }
    }

    .fi-form .afh-block-thumb {
        max-width: 100%;
    }

    .fi-form label:has(.afh-block-thumb) {
        max-width: 170px;
    }

    .fi-form div[wire\:key] div:has( > label) {
        display: flex;
    }
}

/**
* =================================================================
* END Blocks builder
* =================================================================
*/

